 */
public final class TenureFactor {

    private static final int POINTS = 3;

    private static final int TENURE_FISCAL_YEARS = 1;

    private TenureFactor() {
    }

    public static int points(Owner owner) {
        return qualifies(owner) ? POINTS : 0;
    }

